parity_right_click_effect :: proc(user: rawptr, ictx: ^inp.Input, pos: rl.Vector2) {
	wx, wy := rnd.from_screen(ictx.view, pos.x, pos.y)
	was_dragging := ictx.drag.active
	ictx.drag.active = false
	ictx.drag_to = 0
	if was_dragging {
		ictx.press_swallowed = true // an interrupted drag's release must not re-select
	}
	if pid, ok := inp.pipe_hit(ictx.topo, ictx.cat, wx, wy); ok {
		ictx.sel_pipe = i64(pid)
		ictx.sel_node = -1
		ictx.sel_class = 0
		ictx.qos_editing = false
	}
}

