effect_right_click :: proc(user: rawptr, ictx: ^inp.Input, pos: rl.Vector2) {
	app := cast(^App)user
	wx, wy := rnd.from_screen(&app.view, pos.x, pos.y)
	was_dragging := app.input.drag.active
	app.input.drag.active = false
	app.input.drag_to = 0
	if was_dragging {
		app.input.press_swallowed = true // an interrupted drag's release must not re-select
	}
	if pid, ok := inp.pipe_hit(&app.state.topology, &app.cat, wx, wy); ok {
		app.input.sel_pipe = i64(pid)
		app.input.sel_node = -1
		app.input.sel_class = 0
		app.input.qos_editing = false // a fresh selection starts with the editor closed
	}
}
